const shell=document.querySelector(".phone-shell");const screens=[...document.querySelectorAll(".screen")];const nav=[...document.querySelectorAll("[data-nav]")];const sheet=document.getElementById("evidence-sheet");const toast=document.getElementById("toast");const motionToggle=document.getElementById("motion-toggle");const motionState=document.getElementById("reduce-motion-state");function showScreen(id){screens.forEach(s=>s.classList.toggle("active",s.dataset.screen===id));nav.forEach(b=>b.classList.toggle("active",b.dataset.nav===id));window.__ucState={...(window.__ucState||{}),screen:id}}function showToast(message){toast.textContent=message;toast.classList.add("show");clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(()=>toast.classList.remove("show"),1400)}function openEvidence(){sheet.classList.add("open");sheet.setAttribute("aria-hidden","false");window.__ucState={...(window.__ucState||{}),evidenceOpen:true}}function closeEvidence(){sheet.classList.remove("open");sheet.setAttribute("aria-hidden","true");window.__ucState={...(window.__ucState||{}),evidenceOpen:false}}function intent(label){showToast(label+" — نية مالك فقط، بلا تنفيذ حي.");window.__ucState={...(window.__ucState||{}),lastIntent:label}}document.addEventListener("click",e=>{const n=e.target.closest("[data-nav]");if(n){showScreen(n.dataset.nav);return}const a=e.target.closest("[data-action]");if(!a)return;switch(a.dataset.action){case"open-decision":showScreen("decisions");break;case"open-project":showScreen("project");break;case"open-evidence":openEvidence();break;case"close-sheet":closeEvidence();break;case"pause-intent":intent("Pause");break;case"open-activity":showToast("سجل النشاط Prototype فقط.");break;case"ask":showToast("Ask يحفظ السياق؛ لا backend حي.");break;case"approve-intent":intent("Approve");break;case"changes-intent":intent("Request Changes");break;case"reject-intent":intent("Reject");break}});motionToggle.addEventListener("click",()=>{const enabled=motionToggle.getAttribute("aria-pressed")!=="true";motionToggle.setAttribute("aria-pressed",String(enabled));shell.classList.toggle("reduce-motion",enabled);motionState.textContent=enabled?"ON":"OFF";showToast(enabled?"Reduced Motion مفعّل":"Reduced Motion متوقف");window.__ucState={...(window.__ucState||{}),reducedMotion:enabled}});window.__ucState={screen:"home",evidenceOpen:false,reducedMotion:false,runtimeAuthority:false,stage8Opened:false};
